use std::net::{SocketAddr, TcpStream, ToSocketAddrs};
use std::time::Duration;

/// Parse "80", "8000-8100" or "22,80,443" into a port list.
pub fn parse_ports(spec: &str) -> Result<Vec<u16>, String> {
    let mut out = Vec::new();
    for part in spec.split(',') {
        let part = part.trim();
        if let Some((a, b)) = part.split_once('-') {
            let a: u16 = a.parse().map_err(|_| format!("bad port: {a}"))?;
            let b: u16 = b.parse().map_err(|_| format!("bad port: {b}"))?;
            if a > b {
                return Err(format!("empty range: {part}"));
            }
            out.extend(a..=b);
        } else {
            out.push(part.parse().map_err(|_| format!("bad port: {part}"))?);
        }
    }
    Ok(out)
}

pub fn scan(host: &str, ports: &[u16], timeout: Duration) -> Vec<(u16, bool)> {
    ports
        .iter()
        .map(|&p| {
            let open = format!("{host}:{p}")
                .to_socket_addrs()
                .ok()
                .and_then(|mut a| a.next())
                .map(|addr: SocketAddr| TcpStream::connect_timeout(&addr, timeout).is_ok())
                .unwrap_or(false);
            (p, open)
        })
        .collect()
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 3 {
        eprintln!("usage: mini-nmap <host> <ports>");
        std::process::exit(2);
    }
    let ports = match parse_ports(&args[2]) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("{e}");
            std::process::exit(2);
        }
    };
    for (p, open) in scan(&args[1], &ports, Duration::from_millis(200)) {
        if open {
            println!("{p}/tcp OPEN");
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn single() { assert_eq!(parse_ports("80").unwrap(), vec![80]); }
    #[test]
    fn range() { assert_eq!(parse_ports("8-10").unwrap(), vec![8, 9, 10]); }
    #[test]
    fn list() { assert_eq!(parse_ports("22, 80").unwrap(), vec![22, 80]); }
    #[test]
    fn bad() { assert!(parse_ports("x").is_err()); }
}
